test_cmd:
cd backend && mkdir -p "$ENV/home" "$ENV/tmp" && export HOME="$ENV/home" TMPDIR="$ENV/tmp" PYTHONPATH=. PYTHONPYCACHEPREFIX="$ENV/tmp/pycache" OPENAI_API_KEY=sk-dummy && { $PY -m pytest -q -p no:cacheprovider tests/; rc=$?; $PY -c 'import compileall, importlib, sys, time
t = time.time(); ok = 0; bad = []
if compileall.compile_dir("openui", quiet=1, force=True): ok += 1
else: bad.append("compileall openui")
for m in ("openui.server", "openui.litellm", "openui.__main__"):
    try: importlib.import_module(m); ok += 1
    except Exception as e: bad.append(m + ": " + repr(e))
for b in bad: print("SMOKE FAILED " + b)
print("%d passed%s in %.2fs" % (ok, ", %d failed" % len(bad) if bad else "", time.time() - t))
sys.exit(1 if bad else 0)'; s=$?; exit $(( rc > s ? rc : s )); }
